import React, { useState } from "react";
import api from "@landinghub/api";
import Background from "../components/Background";
import { CheckCircle2 } from "lucide-react";
import "../styles/Support.css";

const faqsData = [
  { question: "Làm sao để tạo landing page nhanh chóng?", answer: "Chọn template, kéo thả các thành phần và xuất bản. Không cần kỹ năng code." },
  { question: "Có thể tùy chỉnh layout không?", answer: "LandingHub cho phép chỉnh sửa mọi phần tử, màu sắc, font chữ và bố cục." },
  { question: "Hỗ trợ kỹ thuật như thế nào?", answer: "Chúng tôi có chat trực tuyến và form liên hệ 24/7, đảm bảo phản hồi nhanh chóng." }
];

const Support = () => {
  const [openIndex, setOpenIndex] = useState(null);
  const [form, setForm] = useState({ name: "", email: "", phone: "", notes: "" });
  const [submitted, setSubmitted] = useState(false);

  const toggleFAQ = (index) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.name || !form.email) {
      alert("Tên và Email là bắt buộc!");
      return;
    }
    try {
      await api.post("/api/leads", { ...form, status: "new" });
      setSubmitted(true);
      setForm({ name: "", email: "", phone: "", notes: "" });
      setTimeout(() => setSubmitted(false), 4000);
    } catch (err) {
      console.error(err);
      alert("Gửi thông tin thất bại. Vui lòng thử lại.");
    }
  };

  return (
    <Background showShapes={false} fullWidth={true}>
      <div className="support-page">

        {/* Hero */}
        <section className="support-hero">
          <div className="hero-content">
            <h1>Cần hỗ trợ? Chúng tôi luôn sẵn sàng!</h1>
            <p>LandingHub cung cấp mọi giải pháp để bạn tạo landing page chuyên nghiệp.</p>
          </div>
        </section>

        {/* FAQ Accordion */}
        <section className="faq-section">
          <h2>Câu hỏi thường gặp</h2>
          <div className="faq-list">
            {faqsData.map((faq, idx) => (
              <div
                key={idx}
                className={`faq-card ${openIndex === idx ? "open" : ""}`}
                onClick={() => toggleFAQ(idx)}
              >
                <div className="faq-question">{faq.question}</div>
                <div className="faq-answer">{faq.answer}</div>
              </div>
            ))}
          </div>
        </section>

        {/* Contact Form */}
        <section className="contact-section">
          <div className="contact-card">
            <h2>Liên hệ hỗ trợ trực tuyến</h2>
            {submitted && (
              <div className="success-message">
                <CheckCircle2 size={24} /> Cảm ơn! Chúng tôi đã nhận thông tin của bạn.
              </div>
            )}
            <form className="contact-form" onSubmit={handleSubmit}>
              <input name="name" value={form.name} onChange={handleChange} placeholder="Họ tên" required />
              <input name="email" type="email" value={form.email} onChange={handleChange} placeholder="Email" required />
              <input name="phone" value={form.phone} onChange={handleChange} placeholder="Số điện thoại" />
              <textarea name="notes" value={form.notes} onChange={handleChange} placeholder="Nội dung" />
              <button type="submit" className="btn-submit">Gửi yêu cầu</button>
            </form>
          </div>
        </section>

        {/* CTA Footer */}
        <section className="cta-support">
          <h2>Chúng tôi luôn ở bên bạn</h2>
          <p>Đừng ngần ngại liên hệ để nhận được hỗ trợ nhanh nhất!</p>
          <button className="cta-btn">Liên hệ ngay</button>
        </section>

      </div>
    </Background>
  );
};

export default Support;
